package com.orderflow.cart;
import jakarta.persistence.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.cache.annotation.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.io.Serializable;import java.math.BigDecimal;import java.time.Instant;import java.util.*;
@SpringBootApplication @EnableCaching public class CartApplication{public static void main(String[]a){SpringApplication.run(CartApplication.class,a);}}
@Entity @Table(name="carts",schema="cart")class Cart{@Id UUID id;@Column(name="user_id",unique=true)UUID userId;@Column(name="updated_at")Instant updatedAt;@OneToMany(mappedBy="cart",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)List<CartItem>items=new ArrayList<>();protected Cart(){}Cart(UUID u){id=UUID.randomUUID();userId=u;updatedAt=Instant.now();}}
@Entity @Table(name="cart_items",schema="cart")class CartItem{@Id UUID id;@ManyToOne@JoinColumn(name="cart_id")Cart cart;@Column(name="product_id")UUID productId;@Column(name="product_name")String productName;@Column(name="unit_price")BigDecimal unitPrice;int quantity;protected CartItem(){}CartItem(Cart c,ItemRequest r){id=UUID.randomUUID();cart=c;apply(r);}void apply(ItemRequest r){productId=r.productId();productName=r.productName();unitPrice=r.unitPrice();quantity=r.quantity();}}
interface CartRepo extends JpaRepository<Cart,UUID>{Optional<Cart>findByUserId(UUID u);}record ItemRequest(@NotNull UUID productId,@NotBlank String productName,@NotNull@DecimalMin("0")BigDecimal unitPrice,@Min(1)int quantity){}record ItemView(UUID productId,String productName,BigDecimal unitPrice,int quantity,BigDecimal lineTotal)implements Serializable{}record CartView(UUID userId,List<ItemView>items,BigDecimal total)implements Serializable{}
@Service class CartService{private final CartRepo repo;CartService(CartRepo r){repo=r;}@org.springframework.cache.annotation.Cacheable(value="carts",key="#user")CartView get(UUID user){return view(repo.findByUserId(user).orElseGet(()->new Cart(user)));}@Transactional @CacheEvict(value="carts",key="#user")CartView put(UUID user,ItemRequest req){Cart c=repo.findByUserId(user).orElseGet(()->new Cart(user));c.items.stream().filter(i->i.productId.equals(req.productId())).findFirst().ifPresentOrElse(i->i.apply(req),()->c.items.add(new CartItem(c,req)));c.updatedAt=Instant.now();return view(repo.save(c));}@Transactional @CacheEvict(value="carts",key="#user")CartView remove(UUID user,UUID product){Cart c=repo.findByUserId(user).orElseGet(()->new Cart(user));c.items.removeIf(i->i.productId.equals(product));c.updatedAt=Instant.now();return view(repo.save(c));}private CartView view(Cart c){var items=c.items.stream().map(i->new ItemView(i.productId,i.productName,i.unitPrice,i.quantity,i.unitPrice.multiply(BigDecimal.valueOf(i.quantity)))).toList();return new CartView(c.userId,items,items.stream().map(ItemView::lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add));}}
@RestController @RequestMapping("/api/carts/{userId}")class CartController{private final CartService s;CartController(CartService s){this.s=s;}@GetMapping CartView get(@PathVariable UUID userId,@RequestHeader("X-User-ID")UUID caller,@RequestHeader("X-User-Role")String role){authorize(userId,caller,role);return s.get(userId);}@PutMapping("/items")CartView put(@PathVariable UUID userId,@RequestHeader("X-User-ID")UUID caller,@RequestHeader("X-User-Role")String role,@Valid@RequestBody ItemRequest r){authorize(userId,caller,role);return s.put(userId,r);}@DeleteMapping("/items/{productId}")CartView remove(@PathVariable UUID userId,@PathVariable UUID productId,@RequestHeader("X-User-ID")UUID caller,@RequestHeader("X-User-Role")String role){authorize(userId,caller,role);return s.remove(userId,productId);}private void authorize(UUID requested,UUID caller,String role){if(!requested.equals(caller)&&!"ADMIN".equals(role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"cart belongs to another user");}}
